.task-past-due {
  color: #ff6c6c;
  font-family: var(--jb-font-bold);
}

.task-past-due a {
  color: #ff6c6c;
}

.task-due-today {
  color: #ff811c;
  font-weight: bold;
}

.task-due-today a {
  color: #ff811c;
}

.tasks-list li {
  display: flex;
  color: #999;
}

.tasks-list li h5 {
  font-size: 1.1em;
}

.tasks-list li a {
}

.tasks-list li a:hover {
  color: #262c33;
}

.tasks-list li.mine h5 {
  color: #262c33;
}

.tasks-list li .avatar_group {
  margin-right: 1rem;
}

.tasks-list sl-avatar.team::part(base) {
  color: #262c33;
}

.tasks-list section.info {
  padding-left: 1rem;
}

.tasks-list wa-icon[name="check"] {
  color: var(--jb-color-purple);
}

.edit_time_session ol {
  padding-left: 0;
  list-style: none;
}

.edit_time_session .time-entries .row [class*="col-"]:first-child {
