  font-size: 2em;
}

article.time-session .time-session-clock.running wa-icon {
  color: var(--jb-color-orange);
}

article.time-session .time-session-clock.on-break wa-icon {
  color: var(--jb-color-gray-300);
}

article.time-session .time-session-clock.on-break time {
  color: var(--jb-color-gray-300);
}

article.time-session .time-session-status {
  font-size: 1.5em;
  text-align: center;
  padding: 3em 0 1.5em;
}

article.time-session nav.actions {
